// <diletta-tabs> — a INSTÂNCIA WEB de `design-system-tabs`.
//
// O eixo `Aba` que ela usa foi DECLARADO na spec em 06/09, não derivado: o
// contrato deriva eixo de `enum`, e a seleção de uma aba é índice, não tipo.
// O eixo existia no render e não existia na lei.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-tabs';
const ABA = ['selecionada', 'naoSelecionada', 'desligada'];
const STATUS = ['normal'];

class DilettaTabs extends HTMLElement {
  static observedAttributes = ['abas', 'selecionada', 'desligadas'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.addEventListener('click', (e) => this.aoClicar(e));
    this.addEventListener('keydown', (e) => this.aoTeclar(e));
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  get rotulos() {
    return (this.getAttribute('abas') || '').split('|').map((s) => s.trim()).filter(Boolean);
  }

  /// `filter(Boolean)` ANTES do `Number`, e não depois.
  ///
  /// `''.split(',')` devolve `['']`, e `Number('')` é **0** — não `NaN`. Com o
  /// filtro só de `NaN`, um atributo AUSENTE desligava a primeira aba, e o teste da
  /// linha de marca caiu com "nenhuma aba selecionada". A conversão silenciosa de
  /// vazio para zero é o mesmo tipo de armadilha que `parseInt` tem com espaço.
  get desligadas() {
    return new Set((this.getAttribute('desligadas') || '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean)
      .map(Number)
      .filter((n) => Number.isInteger(n)));
  }

  estadoDe(i) {
    if (this.desligadas.has(i)) return 'desligada';
    return Number(this.getAttribute('selecionada') || 0) === i ? 'selecionada' : 'naoSelecionada';
  }

  seleciona(i) {
    if (this.desligadas.has(i) || i < 0 || i >= this.rotulos.length) return;
    this.setAttribute('selecionada', String(i));
    this.dispatchEvent(new CustomEvent('mudou', { detail: { indice: i }, bubbles: true }));
  }

  aoClicar(e) {
    const alvo = e.composedPath().find((n) => n.dataset && n.dataset.indice !== undefined);
    if (alvo) this.seleciona(Number(alvo.dataset.indice));
  }

  /// Seta anda entre abas, e ela PULA as desligadas — parar numa aba que não
  /// aceita seleção é o teclado levando a pessoa a um beco.
  aoTeclar(e) {
    const passo = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
    if (!passo) return;
    e.preventDefault();
    const n = this.rotulos.length;
    let i = Number(this.getAttribute('selecionada') || 0);
    for (let k = 0; k < n; k++) {
      i = (i + passo + n) % n;
      if (!this.desligadas.has(i)) break;
    }
    this.seleciona(i);
  }

  render() {
    const linhas = this.rotulos.map((rot, i) => {
      const estado = this.estadoDe(i);
      const p = papeisDe(SLUG, { Status: 'normal', Aba: estado });
      const sel = estado === 'selecionada';
      return `<button class="aba" data-indice="${i}" role="tab" type="button"
        aria-selected="${sel}" tabindex="${sel ? 0 : -1}"
        ${estado === 'desligada' ? 'disabled aria-disabled="true"' : ''}
        style="${estiloDa(p).replace(/border-color/g, '--linha')}">${rot}</button>`;
    }).join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .trilho { display: flex; }
        /* O alvo de toque de 44 é PISO e fica no botão, não numa casca em volta:
           aqui a aba É o alvo, diferente do chip, onde a pílula tem desenho
           próprio de 24 que o alvo não pode esticar. */
        .aba {
          background: none;
          /* 48 de altura, medido no Tabbed-controller do arquivo (327x48). O piso
             de alvo de 44 cabe dentro dele, então aqui não há tensão: a aba é o
             alvo e o alvo é maior que o piso.
             Longhand em toda a casa: o atalho de borda reseta o que veio antes. */
          border-width: 0 0 2px; border-style: solid; border-color: var(--linha);
          box-sizing: border-box; height: 48px; min-height: 44px;
          padding: 0 12px; font: inherit; cursor: pointer;
        }
        .aba[disabled] { cursor: default; }
        .aba:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: -3px; }
      </style>
      <div class="trilho" role="tablist">${linhas}</div>`;
  }
}

customElements.define('diletta-tabs', DilettaTabs);
export { DilettaTabs };
